package com.rodrigosambade.androidtesting; import android.app.*;import android.os.*;import android.widget.*; public class MainActivity extends Activity{int n=0;TextView c;@Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);c=findViewById(R.id.counter);findViewById(R.id.increment_button).setOnClickListener(v->{n++;c.setText(String.valueOf(n));});findViewById(R.id.reset_button).setOnClickListener(v->{n=0;c.setText("0");});}}